//autogenerated:yes
//nolint:revive,govet,errcheck
package ualberta_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/ualberta"
)

func TestEnum_UALBERTA_NAV_MODE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.UALBERTA_NAV_MODE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.NAV_AHRS_INIT.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.UALBERTA_NAV_MODE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.NAV_AHRS_INIT, dec)
	})
}
